// Simple Trie Implementation for O(L) lookup where L is length of query
class TrieNode {
    constructor() {
        this.children = {};
        this.isEndOfWord = false;
        this.hotelNames = []; // Store full names at this node for quick retrieval
    }
}

class HotelTrie {
    constructor() {
        this.root = new TrieNode();
    }

    insert(name) {
        let node = this.root;
        for (let char of name.toLowerCase()) {
            if (!node.children[char]) node.children[char] = new TrieNode();
            node = node.children[char];
            node.hotelNames.push(name); // Add name to all prefix nodes
        }
        node.isEndOfWord = true;
    }

    search(prefix) {
        let node = this.root;
        for (let char of prefix.toLowerCase()) {
            if (!node.children[char]) return [];
            node = node.children[char];
        }
        return node.hotelNames.slice(0, 5); // Limit to top 5 results
    }
}

