```csharp
using Microsoft.AspNetCore.Mvc;
using CsvHelper;
using System.Globalization;

[ApiController]
[Route("api/[controller]")]
public class UploadController : ControllerBase
{
    private readonly ICosmosDbService _cosmosService;

    public UploadController(ICosmosDbService cosmosService)
    {
        _cosmosService = cosmosService;
    }

    [HttpPost("upload-csv")]
    public async Task<IActionResult> UploadCsv(IFormFile file)
    {
        if (file == null || file.Length == 0)
            return BadRequest("Please upload a valid CSV file.");

        try
        {
            using var stream = file.OpenReadStream();
            using var reader = new StreamReader(stream);
            using var csv = new CsvReader(reader, CultureInfo.InvariantCulture);

            // Read CSV records into a list of UserRecord objects
            var records = csv.GetRecords<UserRecord>().ToList();

            if (records.Count == 0)
                return BadRequest("The CSV file is empty.");

            await _cosmosService.UploadRecordsAsync(records);

            return Ok(new { Message = $"{records.Count} records uploaded successfully." });
        }
        catch (Exception ex)
        {
            return StatusCode(500, $"Internal server error: {ex.Message}");
        }
    }
}
