#include "HuaweiInverter.hpp"

std::string HuaweiInverter::registersToString(uint16_t* regs, uint8_t count) {
    std::string result = "";
    for (int i = 0; i < count; i++) {
        // Modbus registers are usually Big Endian (High byte first)
        result += (char)((regs[i] >> 8) & 0xFF);
        result += (char)(regs[i] & 0xFF);
    }
    // Remove trailing nulls or spaces
