### 2. `smtp.service.ts`
The service handles the actual logic of creating the transporter and sending the mail.

```typescript
import { Injectable, InternalServerErrorException } from '@nestjs/common';
import * as nodemailer from 'nodemailer';

export interface SmtpOptions {
  host: string;
  port: number;
  secure: boolean;
}

@Injectable()
export class SmtpService {
  private options: SmtpOptions;

  // This method is called by the module factory to set the config
  setOptions(options: SmtpOptions) {
    this.options = options;
  }

  async sendMail(payload: {
    user: string;
    pass: string;
    from: string;
    to: string;
    subject: string;
    html: string;
  }) {
    if (!this.options) {
      throw new InternalServerErrorException('SMTP Service not configured');
    }

    const transporter = nodemailer.createTransport({
      host: this.options.host,
      port: this.options.port,
      secure: this.options.secure,
      auth: {
        user: payload.user,
        pass: payload.pass,
      },
    });

    try {
      const info = await transporter.sendMail({
        from: payload.from,
        to: payload.to,
        subject: payload.subject,
        html: payload.html,
      });
      return { message: 'Email sent successfully', messageId: info.messageId };
    } catch (error) {
      throw new InternalServerErrorException(`Failed to send email: ${error.message}`);
    }
  }
}
```

