import java.util.*

class Minesweeper(val rows: Int, val cols: Int, val minesCount: Int) {
    private val board = Array(rows) { Array(cols) { Cell() } }
    private val revealed = Array(rows) { BooleanArray(cols) }
    private val flagged = Array(rows) { BooleanArray(cols) }
    private var gameOver = false
    private var win = false

    class Cell {
        var isMine = false
        var adjacentMines = 0
    }

    init {
        setupBoard()
    }

    private fun setupBoard() {
        val random = Random()
        var placedMines = 0

        // Place mines randomly
        while (placedMines < minesCount) {
            val r = random.nextInt(rows)
            val c = random.nextInt(cols)
            if (!board[r][c].isMine) {
                board[r][c].isMine = true
                placedMines++
            }
        }

        // Calculate numbers for each cell
        for (r in 0 until rows) {
            for (c in 0 until cols) {
                if (!board[r][c].isMine) {
                    board[r][c].adjacentMines = countMinesAround(r, c)
                }
            }
        }
    }

    private fun countMinesAround(r: Int, c: Int): Int {
        var count = 0
        for (dr in -1..1) {
            for (dc in -1..1) {
                val nr = r + dr
                val nc = c + dc
                if (nr in 0 until rows && nc in 0 until cols && board[nr][nc].isMine) {
                    count++
                }
            }
        }
        return count
    }

