To merge a new interval into a sorted `Vec` of non-overlapping intervals, the most efficient approach is to:
1. Find the range of existing intervals that overlap with the new one.
2. Calculate the new boundaries (the minimum start and maximum end).
3. Remove the overlapping intervals and insert the merged one.

Here is the complete implementation:

```rust
#[derive(Debug, PartialEq, Clone, Copy)]
struct Interval {
    start: i32,
    end: i32,
}

impl Interval {
    fn new(start: i32, end: i32) -> Self {
        Interval { start, end }
    }
}

fn merge_interval(intervals: &mut Vec<Interval>, new_int: Interval) {
    let mut start = new_int.start;
    let mut end = new_int.end;

    // 1. Find the range of intervals that overlap with the new interval
    // An interval [s, e] overlaps with [start, end] if s <= end AND e >= start
    let mut first_overlap = None;
    let mut last_overlap = None;

    for (i, interval) in intervals.iter().enumerate() {
        if interval.start <= end && interval.end >= start {
            if first_overlap.is_none() {
                first_overlap = Some(i);
            }
            last_overlap = Some(i);

            // Update the boundaries of the merged interval
            start = start.min(interval.start);
            end = end.max(interval.end);
        }
    }

    match (first_overlap, last_overlap) {
        (Some(first), Some(last)) => {
            // 2. Remove all overlapping intervals
            // We remove from 'last' down to 'first' to avoid index shifting issues
            intervals.drain(first..=last);

            // 3. Insert the merged interval at the correct sorted position
            intervals.insert(first, Interval::new(start, end));
        }
        _ => {
            // No overlaps found: find the correct insertion point to maintain sort
            let pos = intervals.binary_search_by(|probe| probe.start.cmp(&start))
                .unwrap_or_else(|e| e);
            intervals.insert(pos, Interval::new(start, end));
        }
    }
}

